    /** @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached. */
    fun announce(line: String): UInt {
        val w = UndraWriter()
        w.writeStr(line)
        try {
            val body = this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Workshop.ANNOUNCE),
                UndraIds.Objects.Workshop.ANNOUNCE,
                w.toByteArray(),
            )
            return Codecs.u32.decodeAll(body)
        } catch (e: Exception) {
            throw UndraCallError.mapped(e)
        }
    }

