    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        try {
            when (signalId) {
                0u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u32.decode(reader)
                        reader.finish()
                        _jobs.value = value
                    }
                }
                1u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u32.decode(reader)
                        reader.finish()
                        _notes.value = value
                    }
                }
                else -> Unit
            }
        } catch (e: Exception) {
            core.report(e, "Workshop.apply(signal: $signalId)")
        }
    }

    companion object {
        /** @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached. */
        operator fun invoke(ctx: UndraCore = UndraPlaygroundCore.core): Workshop = create(ctx)

        /** @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached. */
        fun create(ctx: UndraCore = UndraPlaygroundCore.core): Workshop {
            val handle = ctx.constructObject(UndraIds.Objects.Workshop.TYPE_ID, UndraIds.Objects.Workshop.NEW, ByteArray(0))
            return ctx.adopt(handle, ::Workshop)
        }
    }
}

private val codecVecItem = Codecs.vec(Item)
